sequence.script:
mc.setProperty("jwt_usuario", "");
mc.setProperty("jwt_usuario_url", "");
try {
    var assertion = mc.getProperty("x_jwt_assertion_usr");
    if (assertion) {
        var parts = ("" + assertion).split(".");
        if (parts.length === 3) {
            var bytes   = Packages.java.util.Base64.getUrlDecoder().decode(parts[1]);
            var payload = JSON.parse("" + new Packages.java.lang.String(bytes, "UTF-8"));
            var u = payload.sub || payload["http://wso2.org/claims/enduser"] || "";
            u = ("" + u).replace(/@carbon\.super$/, "");
            if (u.length > 0) {
                mc.setProperty("jwt_usuario", u);
                mc.setProperty("jwt_usuario_url",
                    "" + Packages.java.net.URLEncoder.encode(u, "UTF-8").replace(/\+/g, "%20"));
            }
        }
    }
} catch (e) {
    mc.setProperty("dbg_err_usr", "" + e);
}
